def assign_existing_player_codes(apps, schema_editor):
    User = apps.get_model('my_app', 'User')
    PlayerProfile = apps.get_model('my_app', 'PlayerProfile')
    database = schema_editor.connection.alias
    user_ids = PlayerProfile.objects.using(database).values_list('user_id', flat=True)
    for user in User.objects.using(database).filter(pk__in=user_ids, referral_code__isnull=True).iterator():
        while True:
            code = secrets.token_hex(8).upper()
            if not User.objects.using(database).filter(referral_code=code).exists():
                User.objects.using(database).filter(pk=user.pk, referral_code__isnull=True).update(referral_code=code)
                break


